insert into brands (id, name, kit) values ('altus', 'Altus Mountain Guides', '{"fonts":{"display":{"family":"Barlow Condensed","weight":800},"body":{"family":"Source Sans 3","weight":400}},"headlineCase":"upper","defaultPublishTime":"08:30","timezone":"America/Vancouver","logo":{},"colors":{"primary":"#3e6a8f","accent":"#8db7da","ink":"#16191c","paper":"#f3f4f5","overlay":"#0b1620"},"voice":"Certified IFMGA/ACMG mountain guides. Calm, expert, warm. Plain words, short sentences, specific details (routes, huts, dates). Safety-first without fear. No hype, no exclamation stacks, at most one emoji.","rules":["Every post is approved by Ross before it goes out.","Black Friday and other discount offers go to email and the MTN Club only, never the public feed or ads.","Use real prices and dates only when they are in the brief; never invent them.","Credit the photographer when a credit is given."],"hashtags":["#altusmountainguides","#skitouring","#backcountryskiing","#seatosky"],"handle":"@altusmountainguides","website":"https://altusmountainguides.com","defaultCta":"BOOK_TRAVEL"}'::jsonb) on conflict (id) do nothing;
