insert into brands (id, name, kit) values ('winterstoke', 'Winterstoke', '{"fonts":{"display":{"family":"Barlow Condensed","weight":800},"body":{"family":"Source Sans 3","weight":400}},"headlineCase":"upper","defaultPublishTime":"08:30","timezone":"America/Vancouver","logo":{},"colors":{"primary":"#c8792b","accent":"#ffb86b","ink":"#1a120a","paper":"#fbeedf","overlay":"#1a0f05"},"voice":"Community backcountry festival in Squamish. Energetic, welcoming, local. Event details first: what, where, when, price.","rules":["Every post is approved by Ross before it goes out.","Always include venue, date and time for event posts when they are in the brief.","Credit the photographer when a credit is given."],"hashtags":["#winterstoke","#squamish","#backcountry"],"handle":"@winterstoke","website":"","defaultCta":"LEARN_MORE"}'::jsonb) on conflict (id) do nothing;

